<script setup>
import { onMounted, onBeforeUnmount, nextTick, ref } from 'vue';
const props=defineProps({indexUrl:String});const data=ref(null),startDate=ref(''),endDate=ref(''),loading=ref(false),error=ref('');let chart;
const money=v=>'$'+Number(v||0).toLocaleString(undefined,{minimumFractionDigits:2,maximumFractionDigits:2});const number=v=>Number(v||0).toLocaleString();
function makeChart(){if(!window.Chart||!data.value)return;const canvas=document.getElementById('revenueChart');if(!canvas)return;chart?.destroy();chart=new window.Chart(canvas,{type:'line',data:{labels:data.value.revenueByDay.map(x=>x.date),datasets:[{label:'Revenue',data:data.value.revenueByDay.map(x=>Number(x.revenue)),tension:.4,fill:true}]},options:{responsive:true,maintainAspectRatio:false,plugins:{legend:{display:false}},scales:{y:{beginAtZero:true}}}})}
async function load(url=window.location.href,history=false){loading.value=true;error.value='';try{const response=await fetch(url,{headers:{Accept:'application/json','X-Requested-With':'XMLHttpRequest'},credentials:'same-origin'});if(!response.ok)throw new Error('Analytics request failed.');data.value=await response.json();startDate.value=data.value.startDate;endDate.value=data.value.endDate;if(history)window.history.pushState({},'',url);await nextTick();makeChart()}catch(e){error.value=e.message||'Unable to load analytics.'}finally{loading.value=false}}
function apply(){const url=new URL(props.indexUrl,window.location.origin);if(startDate.value)url.searchParams.set('start_date',startDate.value);if(endDate.value)url.searchParams.set('end_date',endDate.value);load(url,true)}function reset(){load(props.indexUrl,true)}function pop(){load(window.location.href)}
onMounted(()=>{window.addEventListener('popstate',pop);load()});onBeforeUnmount(()=>{window.removeEventListener('popstate',pop);chart?.destroy()});
</script>
<template><div class="dashboard-section analytics-page" :aria-busy="loading">
 <div v-if="error" class="alert alert-danger" role="alert">{{ error }} <button class="btn btn-sm btn-outline-danger" @click="load()">Retry</button></div>
 <div class="dashboard-panel mb-4"><div class="panel-header mb-0"><div><h5 class="mb-1">Analytics</h5><p class="text-muted mb-0 small">Monitor your store performance and business insights</p></div></div></div>
 <div class="dashboard-panel mb-4"><form class="analytics-filter" @submit.prevent="apply"><div class="filter-group"><label for="start_date">Start Date</label><input id="start_date" v-model="startDate" type="date"></div><div class="filter-group"><label for="end_date">End Date</label><input id="end_date" v-model="endDate" type="date"></div><div class="filter-actions"><button type="submit" class="btn btn-primary"><i class="bi bi-funnel me-1"></i>Apply Filter</button><button type="button" class="btn btn-light" @click="reset"><i class="bi bi-arrow-counterclockwise me-1"></i>Reset</button></div></form></div>
 <template v-if="data"><div class="row g-4 mb-4"><div v-for="s in [{label:'Total Revenue',value:money(data.totalRevenue),icon:'bi-currency-dollar'},{label:'Total Orders',value:number(data.totalOrders),icon:'bi-bag-check'},{label:'Books Sold',value:number(data.booksSold),icon:'bi-book'},{label:'New Users',value:number(data.newUsers),icon:'bi-people'}]" :key="s.label" class="col-xl-3 col-md-6"><div class="analytics-card"><div class="analytics-card-icon"><i :class="['bi',s.icon]"></i></div><div><span class="analytics-label">{{ s.label }}</span><h4>{{ s.value }}</h4></div></div></div></div>
 <div class="row g-4 mb-4"><div v-for="s in [{label:'Delivered Orders',value:number(data.deliveredOrders)},{label:'Pending Orders',value:number(data.pendingOrders)},{label:'Cancelled Orders',value:number(data.cancelledOrders)},{label:'Average Order Value',value:money(data.averageOrderValue)}]" :key="s.label" class="col-xl-3 col-md-6"><div class="analytics-mini-card"><span>{{ s.label }}</span><strong>{{ s.value }}</strong></div></div></div>
 <div class="dashboard-panel mb-4"><div class="panel-header"><div><h5 class="mb-1">Revenue Analytics</h5><p class="text-muted mb-0 small">Revenue generated during the selected period</p></div></div><div class="analytics-chart-wrapper"><canvas id="revenueChart"></canvas></div></div>
 <div class="row g-4 mb-4"><div class="col-xl-6"><div class="dashboard-panel h-100"><div class="panel-header"><div><h5 class="mb-1">Order Status</h5><p class="text-muted mb-0 small">Orders grouped by current status</p></div></div><div class="analytics-status-list"><div v-for="s in data.ordersByStatus" :key="s.order_status" class="status-row"><div class="status-info"><span>{{ s.order_status.replaceAll('_',' ') }}</span></div><strong>{{ number(s.total) }}</strong></div><div v-if="!data.ordersByStatus.length" class="empty-state"><i class="bi bi-bar-chart"></i><p>No order data available.</p></div></div></div></div><div class="col-xl-6"><div class="dashboard-panel h-100"><div class="panel-header"><div><h5 class="mb-1">Inventory Overview</h5><p class="text-muted mb-0 small">Current book stock information</p></div></div><div class="inventory-grid"><div class="inventory-item"><span>Total Books</span><strong>{{ number(data.totalBooks) }}</strong></div><div class="inventory-item"><span>Low Stock</span><strong>{{ number(data.lowStockBooks) }}</strong></div><div class="inventory-item"><span>Out of Stock</span><strong>{{ number(data.outOfStockBooks) }}</strong></div></div></div></div></div>
 <div class="dashboard-panel mb-4"><div class="panel-header"><div><h5 class="mb-1">Top Selling Books</h5><p class="text-muted mb-0 small">Best performing books during the selected period</p></div></div><div class="table-responsive"><table class="table analytics-table align-middle mb-0"><thead><tr><th>#</th><th>Book</th><th>Units Sold</th><th>Revenue</th></tr></thead><tbody><tr v-for="(b,i) in data.topBooks" :key="b.title+i"><td>{{ i+1 }}</td><td><strong>{{ b.title }}</strong></td><td>{{ number(b.total_sold) }}</td><td>{{ money(b.revenue) }}</td></tr><tr v-if="!data.topBooks.length"><td colspan="4" class="text-center py-4">No sales data available.</td></tr></tbody></table></div></div>
 <div class="dashboard-panel"><div class="panel-header"><div><h5 class="mb-1">Recent Orders</h5><p class="text-muted mb-0 small">Latest orders within the selected period</p></div></div><div class="table-responsive"><table class="table analytics-table align-middle mb-0"><thead><tr><th>Order</th><th>Customer</th><th>Book</th><th>Status</th><th>Total</th></tr></thead><tbody><tr v-for="(o,i) in data.recentOrders" :key="o.order_number+i"><td>{{ o.order_number }}</td><td>{{ o.customer }}</td><td>{{ o.book }}</td><td><span class="analytics-status">{{ o.status.replaceAll('_',' ') }}</span></td><td>{{ money(o.total_price) }}</td></tr><tr v-if="!data.recentOrders.length"><td colspan="5" class="text-center py-4">No recent orders found.</td></tr></tbody></table></div></div></template>
 <div v-else-if="loading" class="dashboard-panel p-4" role="status">Loading analytics…</div>
</div></template>
